class Cache:
    def __init__(self):
        self.cache_storage = {}

    def put(self, key, value):
        """Store the value with the given key."""
        self.cache_storage[key] = value

    def get(self, key):
        """Retrieve the value for the given key, return None if not found."""
        return self.cache_storage.get(key, None)

    def contains(self, key):
        """Return whether the key is currently stored, even when its stored value is None."""
        return key in self.cache_storage

