class Permissions:
    READ = 'read'
    WRITE = 'write'

    def __init__(self):
        self.permissions = {
            'viewer': {self.READ},
            'editor': {self.READ, self.WRITE}
        }

    def allowed(self, role, action):
        if role not in self.permissions:
            return False
        return action in self.permissions[role]

    def grant(self, role, action):
        if role not in self.permissions:
            self.permissions[role] = set()
        self.permissions[role].add(action)
