class Permissions:
    def __init__(self):
        self.permissions = {
            'viewer': ['read'],
            'editor': ['read', 'write']
        }

    def allowed(self, role, action):
        if role not in self.permissions:
            return False
        return action in self.permissions[role]

    def roles_for(self, action):
        roles = []
        for role, actions in self.permissions.items():
            if action in actions:
                roles.append(role)
        return sorted(roles)
